const faqs = [
    {
        pergunta: "A cannabis medicinal faz 'dar barato'?",
        resposta: "Não. Os tratamentos são feitos com canabinoides medicinais (principalmente CBD) em doses terapêuticas que não causam o efeito psicoativo. O objetivo é o alívio dos sintomas, não a intoxicação. O CBD (canabidiol) é um composto não psicoativo que oferece benefícios terapêuticos sem alterar a percepção ou o comportamento."
    },
    {
        pergunta: "É legal usar cannabis medicinal no Brasil?",
        resposta: "Sim. Desde 2022, a Anvisa regulamentou o acesso a produtos à base de cannabis mediante prescrição médica. O médico pode prescrever produtos importados ou manipulados em farmácias autorizadas. A Resolução RDC n.º 660 estabelece os critérios para importação de produtos derivados da cannabis."
    },
    {
        pergunta: "Quanto tempo leva para fazer efeito?",
        resposta: "O tempo de resposta varia conforme a condição tratada, a via de administração e a individualidade de cada paciente. Alguns pacientes relatam melhora em dias, enquanto outros precisam de algumas semanas para ajuste da dose. O tratamento é personalizado e o acompanhamento médico é essencial para otimizar os resultados."
    },
    {
        pergunta: "Posso parar meus outros medicamentos?",
        resposta: "Nunca pare medicamentos prescritos sem orientação médica. A cannabis medicinal pode ser usada como coadjuvante ou, em alguns casos, permitir a redução gradual de outros medicamentos, mas isso deve ser feito sob supervisão médica especializada. O acompanhamento contínuo garante a segurança e eficácia do tratamento."
    },
    {
        pergunta: "O tratamento é seguro?",
        resposta: "Quando prescrito e acompanhado por um médico especializado, o tratamento com cannabis medicinal é seguro. O CBD tem perfil de segurança favorável, sendo bem tolerado mesmo em doses elevadas. A Organização Mundial da Saúde (OMS) reconhece o CBD como uma substância segura e não adictiva."
    },
    {
        pergunta: "Quais condições podem ser tratadas?",
        resposta: "A cannabis medicinal tem demonstrado benefícios em diversas condições, incluindo: epilepsia refratária, ansiedade generalizada, insônia, TDAH, dores crônicas, fibromialgia, endometriose, TEPT, cessação do tabagismo, dependência química, hipertensão e mais. Cada caso é avaliado individualmente."
    }
];
